from __future__ import annotations

import typing

import pytest

from llm_router._internal.capabilities.schema import (
    _validate_mapping_schema_definition,
)

pytestmark = pytest.mark.verification_kind("unit")


class ReadOnlySchema(typing.Mapping[str, typing.Any]):
    """A non-dict Mapping wrapping plain schema data."""

    def __init__(self, data: dict[str, typing.Any]) -> None:
        self._data = data

    def __getitem__(self, key: str) -> typing.Any:
        return self._data[key]

    def __iter__(self) -> typing.Iterator[str]:
        return iter(self._data)

    def __len__(self) -> int:
        return len(self._data)


@pytest.mark.verifies("REQ_STRUCTURED_SCHEMA_CONTRACT[revision==2]")
def test_read_only_mapping_object_schema_is_accepted() -> None:
    schema = ReadOnlySchema(
        {
            "title": "answer_payload",
            "type": "object",
            "properties": {"answer": {"type": "string"}},
            "required": ["answer"],
        }
    )

    assert not isinstance(schema, dict)
    assert _validate_mapping_schema_definition(schema) is None
